/**
 * Which keys a gateway accepts. Keys are secrets the vendor issues; a key
 * that is short or shares text with this server's own texts is refused, so
 * no text of ours (a marker, a placeholder, a log prefix, a file name, an
 * error or a variable name) can ever hold a piece of a key, and redaction
 * can never leave a key in place.
 *
 * - At least MIN_KEY_LENGTH characters.
 * - No piece of KEY_FRAGMENT_LENGTH characters of the key occurs in
 *   FIXED_CORPUS: every string literal in src/, generated by
 *   scripts/fixed-corpus.mjs and kept up to date by a test.
 *
 * The refusal never quotes the key: it is a fixed text with every run that
 * shares a piece with the key masked as "…", so even a key copied from the
 * refusal itself is not repeated.
 */
import { FIXED_CORPUS } from './fixed-corpus.generated.js';

export const MIN_KEY_LENGTH = 16;
export const KEY_FRAGMENT_LENGTH = 6;
export const KEY_REFUSED = 'The key was refused: it is too short, or it shares text with this server’s own texts.';

let corpusPieces: Set<string> | undefined;

function pieces(): Set<string> {
  if (!corpusPieces) {
    corpusPieces = new Set();
    for (const text of [...FIXED_CORPUS, KEY_REFUSED]) {
      for (let i = 0; i + KEY_FRAGMENT_LENGTH <= text.length; i += 1) {
        corpusPieces.add(text.slice(i, i + KEY_FRAGMENT_LENGTH));
      }
    }
  }
  return corpusPieces;
}

/** Whether a gateway accepts this key. */
export function admitsKey(value: string): boolean {
  if (typeof value !== 'string' || value.length < MIN_KEY_LENGTH) {
    return false;
  }
  const corpus = pieces();
  for (let i = 0; i + KEY_FRAGMENT_LENGTH <= value.length; i += 1) {
    if (corpus.has(value.slice(i, i + KEY_FRAGMENT_LENGTH))) {
      return false;
    }
  }
  return true;
}

/** KEY_REFUSED with every run that shares a piece with the key masked, so the refusal holds no piece of it. */
export function keyRefusedText(value: unknown): string {
  const key = typeof value === 'string' ? value : '';
  const own = new Set<string>();
  for (let i = 0; i + KEY_FRAGMENT_LENGTH <= key.length; i += 1) {
    own.add(key.slice(i, i + KEY_FRAGMENT_LENGTH));
  }
  const text = KEY_REFUSED;
  const covered = new Uint8Array(text.length);
  for (let i = 0; i + KEY_FRAGMENT_LENGTH <= text.length; i += 1) {
    if (own.has(text.slice(i, i + KEY_FRAGMENT_LENGTH))) covered.fill(1, i, i + KEY_FRAGMENT_LENGTH);
  }
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    if (!covered[i]) out += text[i];
    else if (i === 0 || !covered[i - 1]) out += '…';
  }
  return out;
}
